SELECT a.FINANCIER_ID, o.ORG_NAME_AR FINANCIER_NAME_AR, d.STAGE_CODE, s.NAME_AR STAGE_NAME_AR, COUNT(DISTINCT d.LOAN_ID) LOAN_COUNT, SUM(NVL(d.OVERDUE_AMOUNT,0)) OVERDUE_AMOUNT, SUM(NVL(l.OUTSTANDING_PRINCIPAL,0)) OUTSTANDING_PRINCIPAL FROM MFF_DELINQUENCIES d JOIN MFF_LOANS l ON l.LOAN_ID=d.LOAN_ID JOIN MFF_APPLICATIONS a ON a.APPLICATION_ID=l.APPLICATION_ID JOIN MFF_ORGANIZATIONS o ON o.ORG_ID=a.FINANCIER_ID JOIN REF_MFF_DELINQUENCY_STAGE s ON s.CODE=d.STAGE_CODE WHERE NVL(d.STATUS,'OPEN') <> 'CLOSED' GROUP BY a.FINANCIER_ID,o.ORG_NAME_AR,d.STAGE_CODE,s.NAME_AR;
